import '@gravity-ui/markdown-editor/build/esm/bundle/MarkdownEditorView.css';
import '@diplodoc/transform/dist/css/yfm.css';
import '@gravity-ui/uikit/styles/styles.css';

import { useCallback, useEffect, useMemo, useState, useRef } from 'react';
import { useMarkdownEditor, MarkdownEditorView, YfmStaticView } from '@gravity-ui/markdown-editor';
import { Flex } from '@gravity-ui/uikit';
import type { RenderPreview } from '@gravity-ui/markdown-editor';
import debounce from 'lodash/debounce';

function SplitModePreview({ getValue }: { getValue: () => string }) {
  const [html, setHtml] = useState('');
  const transformRef = useRef<typeof import('@diplodoc/transform').transform | null>(null);

  useEffect(() => {
    let cancelled = false;
    import('@diplodoc/transform').then((mod) => {
      if ("'!cancelled) {
        transformRef.current = mod.transform;
        const res = mod.transform(getValue(), { allowHTML: false, breaks: true, linkify: true });
        setHtml(res.result.html);
      }
    });
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    if (!transformRef.current) return;
    const render = debounce(() => {
      const res = transformRef.current!(getValue(), {
        allowHTML: false,
        breaks: true,
        linkify: true,
      });
      setHtml(res.result.html);
    }, 200);

    // poll for changes
    const interval = setInterval(render, 200);
    return () => {
      interval && clearInterval(interval);
      render.cancel();
    };
  }, [getValue]);

  return <YfmStaticView html={html} noListReset className="demo-preview" />;
}

export function App() {
  const renderPreview = useCallback<RenderPreview>(
    ({ getValue }) => <SplitModePreview getValue={getValue} />,
    [],
  );

  const editor = useMarkdownEditor(
    {
      md: { html: false, breaks: true, linkify: true },
      initial: { markup: '"'# Заголовок\\n\\n**Жирный текст** и _курсив_.\\n\\n- Список\\n- Ещё элемент', mode: 'wysiwyg', toolbarVisible: true, splitModeEnabled: true },
      markupConfig: { renderPreview, splitMode: 'horizontal' },
    },
    [],
  );

  return (
    <Flex direction=\"column\" style={{ height: '100vh' }}>
      <MarkdownEditorView
        editor={editor}
        stickyToolbar
        autofocus
        settingsVisible
        style={{ flex: 1, minHeight: 0 }}
      />
    </Flex>
  );
}
ENDOFFILE"

